Ders: Döngünün bir çıkış kapısı (i++) olmak zorundadır.

private void btnListele_Click(object sender, EventArgs e)
{
    try
    {
        int baslangic = Convert.ToInt32(txtBaslangic.Text);
        int bitis = Convert.ToInt32(txtBitis.Text);
        int adim = Convert.ToInt32(txtAdim.Text);

        listBox1.Items.Clear();
        int toplam = 0;
        int sayac = 0;

        for (int i = baslangic; i <= bitis; i += adim)
        {
            listBox1.Items.Add("Sayı: " + i);
            toplam += i; // Kumbaraya at
            sayac++;     // Adet say
        }
        lblOzet.Text = "Adet: " + sayac + " | Toplam: " + toplam;
    }
    catch { MessageBox.Show("Lütfen geçerli sayılar giriniz!"); }
}

private void btnCarpimTablosu_Click(object sender, EventArgs e)
{
    listBox1.Items.Clear();
    for (int i = 1; i <= 5; i++) // Dış Döngü (Gruplar)
    {
        for (int j = 1; j <= 10; j++) // İç Döngü (Satırlar)
        {
            listBox1.Items.Add(i + " x " + j + " = " + (i * j));
        }
        listBox1.Items.Add("--------------------");
    }
}

